// Ajuste aqui: quantos cardápios a mesma rede pode criar por hora e por quantos dias o cardápio fica no ar
const LIMITE_POR_HORA = 20;
const VALIDADE_DIAS = 180;

const req = $('Novo cardápio (POST)').first().json;
const b = (req.body && typeof req.body === 'object') ? req.body : {};
const usos = Number(Object.values($input.first().json)[0]) || 0;
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const erros = [];

const d = {
  nome: limpa(b.nome, 60),
  tipo: limpa(b.tipo, 40) || 'Restaurante',
  estilo: limpa(b.estilo, 40) || 'moderno e vibrante',
  endereco: limpa(b.endereco, 160),
  horario: limpa(b.horario, 80),
  instagram: limpa(b.instagram, 40).replace(/^@+/, '').replace(/[^\w.]/g, ''),
  cardapio_texto: String(b.cardapio_texto ?? '').replace(/\r/g, '').slice(0, 6000).trim(),
  entrega: b.entrega === true || b.entrega === 'on' || b.entrega === 'true',
  retirada: b.retirada === true || b.retirada === 'on' || b.retirada === 'true',
  taxa: 0,
  whatsapp: '',
};
if (d.nome.length < 2) erros.push('Preencha o nome do estabelecimento.');
if (d.cardapio_texto.length < 15) erros.push('Cole o cardápio com os preços.');
if (!d.entrega && !d.retirada) d.retirada = true;

const taxa = Number(String(b.taxa || '').replace(/[^\d,.]/g, '').replace(',', '.'));
if (d.entrega && taxa > 0 && taxa < 200) d.taxa = Math.round(taxa * 100) / 100;

let zap = String(b.whatsapp || '').replace(/\D/g, '');
if (zap.length === 10 || zap.length === 11) zap = '55' + zap;
if (zap.length >= 12 && zap.length <= 13) d.whatsapp = zap; else erros.push('WhatsApp inválido: use DDD + número.');

// Pix: a chave fica só na configuração privada; o cardápio público só sabe se aceita Pix
const pix = { ativo: false };
if (b.pix === true || b.pix === 'on' || b.pix === 'true') {
  const tipo = limpa(b.pix_tipo, 12);
  let chave = limpa(b.pix_chave, 80);
  const dig = chave.replace(/\D/g, '');
  if (tipo === 'cpf' && dig.length === 11) chave = dig;
  else if (tipo === 'cnpj' && dig.length === 14) chave = dig;
  else if (tipo === 'celular' && (dig.length === 10 || dig.length === 11 || ((dig.length === 12 || dig.length === 13) && dig.startsWith('55')))) chave = '+' + (dig.startsWith('55') && dig.length > 11 ? dig : '55' + dig);
  else if (tipo === 'email' && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(chave)) chave = chave.toLowerCase();
  else if (tipo === 'aleatoria' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(chave)) chave = chave.toLowerCase();
  else { erros.push('Chave Pix inválida para o tipo escolhido.'); chave = ''; }
  if (chave) Object.assign(pix, { ativo: true, chave, nome: limpa(b.pix_nome, 40) || d.nome, cidade: limpa(b.pix_cidade, 40) || 'BRASIL' });
}

let codigo_http = 400;
if (String(b.site || '').trim()) erros.push('Requisição recusada.');
if (usos > LIMITE_POR_HORA) { erros.unshift('Muitos cardápios criados nesta rede na última hora. Tente mais tarde.'); codigo_http = 429; }

const rnd = n => Array.from({ length: n }, () => 'abcdefghijkmnpqrstuvwxyz23456789'[Math.floor(Math.random() * 32)]).join('');
const slug = (d.nome.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 30) || 'cardapio') + '-' + rnd(4);
const chave_painel = rnd(20);
const base = String(req.webhookUrl || '').split('/webhook/')[0] || 'https://webhookn8n6.inovareinteligenciaartificial.com';

return [{ json: {
  valido: erros.length === 0, erros, codigo_http, slug, dados: d,
  privado: { chave_painel, pix, whatsapp: d.whatsapp },
  links: { cardapio: `${base}/webhook/cardapio?c=${slug}`, painel: `${base}/webhook/cardapio-painel?c=${slug}&k=${chave_painel}` },
  ttl: VALIDADE_DIAS * 86400,
  criadoEm: new Date().toISOString(),
} }];

