function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

const cad = $('Validar cadastro').first().json;
const bruto = $input.first().json.output ?? '';
const ia = parseJSON(bruto);
const limpa = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const TAGS = ['vegetariano', 'vegano', 'picante', 'sem_gluten', 'sem_lactose', 'mais_pedido'];

function preco(v) {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').replace(/[^\d,.]/g, '');
  if (!s) return null;
  const n = Number(s.includes(',') ? s.replace(/\./g, '').replace(',', '.') : s);
  return Number.isFinite(n) ? n : null;
}

// Leitor de reserva: usado quando a IA falha. Lê "nome ... preço" no fim da linha.
function leitorReserva(texto) {
  const cats = []; let atual = null;
  for (const linha0 of texto.split('\n')) {
    const linha = linha0.trim();
    if (!linha) continue;
    const m = linha.match(/^(.*?)[\s.\-–:|]*(?:R\$\s*)?(\d{1,4}(?:[.,]\d{1,2})?)\s*$/i);
    if (m && m[1].replace(/[^a-zA-ZÀ-ú]/g, '').length >= 2) {
      if (!atual) { atual = { nome: 'Cardápio', emoji: '🍽️', itens: [] }; cats.push(atual); }
      atual.itens.push({ nome: m[1].replace(/[\s.\-–:|]+$/, ''), preco: preco(m[2]), descricao_original: '', tags: [] });
    } else if (linha.length <= 40) {
      atual = { nome: linha.replace(/[:\-–]+$/, ''), emoji: '🍽️', itens: [] }; cats.push(atual);
    }
  }
  return cats.filter(c => c.itens.length);
}

let origem = 'ia', categorias = Array.isArray(ia && ia.categorias) ? ia.categorias : [];
if (!categorias.some(c => Array.isArray(c.itens) && c.itens.length)) { categorias = leitorReserva(cad.dados.cardapio_texto); origem = 'reserva'; }

let n = 0;
const avisos = (ia && Array.isArray(ia.avisos) ? ia.avisos : []).map(a => limpa(a, 160)).filter(Boolean).slice(0, 10);
const final = categorias.slice(0, 20).map((c, ci) => ({
  id: 'c' + (ci + 1),
  nome: limpa(c.nome, 40) || 'Outros',
  emoji: /[\u{1FA70}-\u{1FAFF}\u{1F971}-\u{1F97F}\u{1F9A3}-\u{1F9AF}\u{1F9CB}-\u{1F9CF}]/u.test(limpa(c.emoji, 4)) ? '🍽️' : (limpa(c.emoji, 4) || '🍽️'),
  itens: (Array.isArray(c.itens) ? c.itens : []).slice(0, 60).map(it => {
    const p = preco(it.preco);
    return {
      id: 'i' + (++n),
      nome: limpa(it.nome, 70),
      preco: p !== null && p >= 0 && p < 100000 ? Math.round(p * 100) / 100 : null,
      descricao: limpa(it.descricao_original, 200),
      tags: (Array.isArray(it.tags) ? it.tags : []).map(t => String(t).toLowerCase()).filter(t => TAGS.includes(t)),
    };
  }).filter(it => it.nome.length >= 2),
})).filter(c => c.itens.length);

const semPreco = final.flatMap(c => c.itens).filter(i => i.preco === null).map(i => i.nome);
if (semPreco.length) avisos.push(`Sem preço (aparecem como "consulte"): ${semPreco.slice(0, 5).join(', ')}${semPreco.length > 5 ? '…' : ''}`);
const resumo = final.flatMap(c => c.itens.map(i => `${i.id} | ${c.nome} | ${i.nome} | ${i.preco === null ? 'sem preço' : 'R$ ' + i.preco.toFixed(2)} | ${i.descricao}`)).join('\n');

const total = final.reduce((s, c) => s + c.itens.length, 0);
return [{ json: { ok: total > 0, origem, categorias: final, avisos, total_itens: total, resumo_itens: resumo } }];

