function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

const base = $('Conferir itens').first().json;
const cad = $('Validar cadastro').first().json;
const ia = parseJSON($input.first().json.output ?? '') || {};
const limpa = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const categorias = JSON.parse(JSON.stringify(base.categorias));
const porId = {};
categorias.forEach(c => c.itens.forEach(i => { porId[i.id] = i; }));

const desc = (ia.descricoes && typeof ia.descricoes === 'object') ? ia.descricoes : {};
let descritos = 0;
for (const [id, t] of Object.entries(desc)) {
  if (porId[id] && limpa(t, 140).length > 8) { porId[id].descricao = limpa(t, 140); descritos++; }
}

const destaques = (Array.isArray(ia.destaques) ? ia.destaques : []).filter(id => porId[id]).slice(0, 3);
destaques.forEach(id => { if (!porId[id].tags.includes('mais_pedido')) porId[id].tags.push('mais_pedido'); });

const combos = (Array.isArray(ia.combos) ? ia.combos : []).slice(0, 3).map(c => {
  const ids = (Array.isArray(c.itens) ? c.itens : []).filter(id => porId[id] && porId[id].preco !== null).slice(0, 5);
  const soma = ids.reduce((s, id) => s + porId[id].preco, 0);
  let p = Number(c.preco_sugerido);
  if (!Number.isFinite(p) || p <= 0 || p > soma || p < soma * 0.7) p = soma * 0.92;
  return { id: '', nome: limpa(c.nome, 50), descricao: limpa(c.descricao, 140), itens: ids, preco: Math.round(p * 10) / 10, soma: Math.round(soma * 100) / 100 };
}).filter(c => c.nome && c.itens.length >= 2).map((c, i) => ({ ...c, id: 'k' + (i + 1) }));

return [{ json: {
  categorias, combos,
  slogan: limpa(ia.slogan, 70),
  boas_vindas: limpa(ia.boas_vindas, 160) || `Bem-vindo ao ${cad.dados.nome}! Escolha seus favoritos e faça o pedido pelo WhatsApp.`,
  textos_ia: descritos > 0,
} }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

const cad = $('Validar cadastro').first().json;
const txt = $('Aplicar textos').first().json;
const ia = parseJSON($input.first().json.output ?? '') || {};
const d = cad.dados;
const hex = v => /^#[0-9a-f]{6}$/i.test(String(v || '').trim()) ? String(v).trim().toLowerCase() : null;
const fonte = v => /^[A-Za-z][A-Za-z0-9 ]{1,40}$/.test(String(v || '').trim()) ? String(v).trim() : null;

const PRESETS = {
  'moderno e vibrante': { tema: 'claro', primaria: '#e4572e', secundaria: '#f3a712', fundo: '#fffaf5', superficie: '#ffffff', texto: '#22160f', texto_suave: '#6f5d50', destaque: '#2e9e5b', fonte_titulo: 'Poppins', fonte_corpo: 'Nunito Sans', emoji_capa: '🔥' },
  'rústico e artesanal': { tema: 'claro', primaria: '#8c4a2f', secundaria: '#c98b52', fundo: '#f8f1e7', superficie: '#fffaf2', texto: '#2d1d12', texto_suave: '#6e5848', destaque: '#5b7f3a', fonte_titulo: 'Fraunces', fonte_corpo: 'Lato', emoji_capa: '🪵' },
  'elegante e sofisticado': { tema: 'escuro', primaria: '#c9a227', secundaria: '#7a5c12', fundo: '#121212', superficie: '#1d1d1d', texto: '#f4efe6', texto_suave: '#b7ab98', destaque: '#c9a227', fonte_titulo: 'Playfair Display', fonte_corpo: 'Inter', emoji_capa: '✨' },
  'natural e saudável': { tema: 'claro', primaria: '#2f855a', secundaria: '#9ccc65', fundo: '#f5fbf4', superficie: '#ffffff', texto: '#163020', texto_suave: '#55705e', destaque: '#e07a1f', fonte_titulo: 'Outfit', fonte_corpo: 'Inter', emoji_capa: '🌿' },
  'divertido e colorido': { tema: 'claro', primaria: '#d6336c', secundaria: '#7048e8', fundo: '#fff7fb', superficie: '#ffffff', texto: '#2a1530', texto_suave: '#6c5a73', destaque: '#f59f00', fonte_titulo: 'Baloo 2', fonte_corpo: 'Nunito', emoji_capa: '🎉' },
  'escuro e urbano': { tema: 'escuro', primaria: '#ff6b1a', secundaria: '#ffb347', fundo: '#0f0f10', superficie: '#1a1a1c', texto: '#f5f5f5', texto_suave: '#a8a8ad', destaque: '#ff6b1a', fonte_titulo: 'Syne', fonte_corpo: 'Inter', emoji_capa: '🍔' },
};
const p = PRESETS[d.estilo] || PRESETS['moderno e vibrante'];
const design = { tema: ia.tema === 'escuro' ? 'escuro' : ia.tema === 'claro' ? 'claro' : p.tema };
let ok = true;
for (const k of ['primaria', 'secundaria', 'fundo', 'superficie', 'texto', 'texto_suave', 'destaque']) {
  const v = hex(ia[k]); if (!v) ok = false; design[k] = v || p[k];
}
if (!ok) Object.assign(design, p);
design.fonte_titulo = fonte(ia.fonte_titulo) || p.fonte_titulo;
design.fonte_corpo = fonte(ia.fonte_corpo) || p.fonte_corpo;
// Emojis muito novos (Unicode 12+) viram quadradinho em Windows antigos: nesse caso usa o do estilo
const emojiNovo = e => /[\u{1FA70}-\u{1FAFF}\u{1F971}-\u{1F97F}\u{1F9A3}-\u{1F9AF}\u{1F9CB}-\u{1F9CF}]/u.test(e);
const emo = String(ia.emoji_capa || '').trim().slice(0, 4);
design.emoji_capa = emo && !emojiNovo(emo) ? emo : p.emoji_capa;
const fam = f => encodeURIComponent(f).replace(/%20/g, '+');
design.fonts_href = `https://fonts.googleapis.com/css2?family=${fam(design.fonte_titulo)}:wght@600;700;800&family=${fam(design.fonte_corpo)}:wght@400;600;700&display=swap`;

const menu = {
  slug: cad.slug,
  loja: { nome: d.nome, tipo: d.tipo, slogan: txt.slogan, boas_vindas: txt.boas_vindas, endereco: d.endereco, horario: d.horario,
          instagram: d.instagram, entrega: d.entrega, taxa: d.taxa, retirada: d.retirada, aceita_pix: cad.privado.pix.ativo },
  design, categorias: txt.categorias, combos: txt.combos,
  atualizadoEm: new Date().toISOString(),
};
const segundos = Math.round((Date.now() - new Date(cad.criadoEm).getTime()) / 1000);
return [{ json: { menu_str: JSON.stringify(menu), design_ia: ok, segundos,
  status_str: JSON.stringify({ status: 'pronto', etapa: 4, mensagem: 'Cardápio publicado', segundos, design_ia: ok, textos_ia: txt.textos_ia,
    itens: menu.categorias.reduce((s, c) => s + c.itens.length, 0), atualizadoEm: new Date().toISOString() }) } }];

const q = $('Abrir cardápio (GET)').first().json.query || {};
const slug = String(q.c || '');
const valido = /^[a-z0-9-]{4,60}$/.test(slug);
let st = null, menu = null;
try { st = valido ? JSON.parse($('Lê status do cardápio').first().json.status || 'null') : null; } catch (e) {}
try { menu = valido ? JSON.parse($('Lê cardápio pronto').first().json.menu || 'null') : null; } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const brl = v => 'R$ ' + Number(v).toFixed(2).replace('.', ',');

function simples(titulo, corpo, refresh) {
  return `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">${refresh ? '<meta http-equiv="refresh" content="4">' : ''}<title>${esc(titulo)}</title>
<style>*{box-sizing:border-box;margin:0}body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#fff8ef;color:#2b1d14;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;text-align:center}.c{max-width:440px;background:#fff;border-radius:22px;padding:34px 26px;box-shadow:0 12px 34px rgba(43,29,20,.1)}h1{font-size:23px;margin:14px 0 8px}p{color:#7a6656;line-height:1.55}.e{font-size:52px}.s{width:44px;height:44px;border:4px solid #f3e3d1;border-top-color:#e4572e;border-radius:50%;margin:0 auto;animation:r .8s linear infinite}@keyframes r{to{transform:rotate(360deg)}}ol{list-style:none;text-align:left;margin:18px 0 0;padding:0}li{padding:9px 12px;border-radius:12px;margin-top:6px;background:#fff8ef;color:#a08b7a;font-weight:600}li.on{background:#ffe8dc;color:#c0441d}li.ok{color:#2e9e5b}</style></head><body><div class="c">${corpo}</div></body></html>`;
}

if (!st) {
  return [{ json: { codigo: 404, html: simples('Cardápio não encontrado', '<div class="e">🍽️</div><h1>Cardápio não encontrado</h1><p>Este link não existe ou expirou.</p>') } }];
}
if (st.status === 'erro') {
  return [{ json: { codigo: 500, html: simples('Não foi possível montar', `<div class="e">😕</div><h1>Não conseguimos montar este cardápio</h1><p>${esc(st.mensagem)}</p>`) } }];
}
if (st.status !== 'pronto' || !menu) {
  const etapas = ['Organizando os itens e preços', 'Escrevendo descrições e combos', 'Escolhendo cores e fontes', 'Publicando o cardápio'];
  const lista = etapas.map((t, i) => `<li class="${i + 1 < st.etapa ? 'ok' : i + 1 === st.etapa ? 'on' : ''}">${i + 1 < st.etapa ? '✓' : i + 1 === st.etapa ? '⏳' : '•'} ${t}</li>`).join('');
  return [{ json: { codigo: 200, html: simples('Montando o cardápio…', `<div class="s"></div><h1>Montando seu cardápio</h1><p>A IA está trabalhando. Esta tela se atualiza sozinha.</p><ol>${lista}</ol>`, true) } }];
}

const L = menu.loja, D = menu.design, escuro = D.tema === 'escuro';
const precos = {}, nomes = {};
menu.categorias.forEach(c => c.itens.forEach(i => { if (i.preco !== null) { precos[i.id] = i.preco; nomes[i.id] = i.nome; } }));
(menu.combos || []).forEach(k => { precos[k.id] = k.preco; nomes[k.id] = k.nome; });
const TAG = { vegetariano: '🌱 Vegetariano', vegano: '🌿 Vegano', picante: '🌶️ Picante', sem_gluten: 'Sem glúten', sem_lactose: 'Sem lactose', mais_pedido: '⭐ Mais pedido' };

const card = (id, nome, desc, preco, tags, extra = '', classe = '') => `
<article class="item ${classe}" data-id="${id}" data-busca="${esc((nome + ' ' + desc).toLowerCase())}">
  <div class="top"><h3>${esc(nome)}</h3></div>
  ${desc ? `<p>${esc(desc)}</p>` : ''}
  ${tags.length ? `<div class="tags">${tags.map(t => `<span class="tag">${TAG[t] || esc(t)}</span>`).join('')}</div>` : ''}
  <div class="pb"><span class="preco">${extra}${preco === null ? 'Consulte' : brl(preco)}</span>
  ${preco === null ? '' : `<button class="add" type="button" data-add="${id}" aria-label="Adicionar ${esc(nome)}">+ Adicionar</button>
  <span class="qtd"><button type="button" data-dec="${id}" aria-label="Remover um">−</button><b data-q="${id}">0</b><button type="button" data-add="${id}" aria-label="Adicionar mais um">+</button></span>`}</div>
</article>`;

const secoes = [];
const chips = [];
if ((menu.combos || []).length) {
  chips.push(`<a href="#combos">🔥 Combos</a>`);
  secoes.push(`<section class="cat" id="combos"><h2>🔥 Combos da casa</h2><div class="grid">${menu.combos.map(k =>
    card(k.id, k.nome, k.descricao || k.itens.map(i => nomes[i]).filter(Boolean).join(' + '), k.preco, [], k.soma > k.preco ? `<span class="de">${brl(k.soma)}</span>` : '', 'combo')).join('')}</div></section>`);
}
menu.categorias.forEach(c => {
  chips.push(`<a href="#${c.id}">${esc(c.emoji)} ${esc(c.nome)}</a>`);
