<script type="application/json" id="dados">${dados}</script>
<script>
(function () {
  var M = JSON.parse(document.getElementById('dados').textContent);
  var KEY = 'carrinho_' + M.slug, cart = {};
  try { cart = JSON.parse(localStorage.getItem(KEY) || '{}'); } catch (e) {}
  var $ = function (s) { return document.querySelector(s); }, all = function (s) { return document.querySelectorAll(s); };
  var brl = function (v) { return 'R$ ' + v.toFixed(2).replace('.', ','); };
  function salvar() { try { localStorage.setItem(KEY, JSON.stringify(cart)); } catch (e) {} }
  function tipo() { var r = document.querySelector('input[name=tipo]:checked'); return r ? r.value : 'retirada'; }
  function subtotal() { var s = 0; Object.keys(cart).forEach(function (id) { if (M.precos[id] != null) s += M.precos[id] * cart[id]; }); return s; }
  function taxa() { return tipo() === 'entrega' ? M.taxa : 0; }
  function render() {
    var n = 0;
    Object.keys(cart).forEach(function (id) { if (M.precos[id] == null || cart[id] <= 0) delete cart[id]; else n += cart[id]; });
    all('.item').forEach(function (el) { var id = el.getAttribute('data-id'), q = cart[id] || 0; el.classList.toggle('sel', q > 0); var b = el.querySelector('[data-q]'); if (b) b.textContent = q; });
    $('#barra').style.display = n ? 'block' : 'none';
    $('#qtdTot').textContent = n + (n === 1 ? ' item' : ' itens');
    $('#valTot').textContent = brl(subtotal());
    $('#linhas').innerHTML = Object.keys(cart).map(function (id) {
      return '<div class="linha"><span>' + cart[id] + 'x ' + esc(M.nomes[id]) + '<br><small style="color:var(--mu)">' + brl(M.precos[id] * cart[id]) + '</small></span><span class="qtd"><button type="button" data-dec="' + id + '">−</button><b>' + cart[id] + '</b><button type="button" data-add="' + id + '">+</button></span></div>';
    }).join('') || '<p style="color:var(--mu)">Seu carrinho está vazio.</p>';
    $('#endBox').style.display = tipo() === 'entrega' ? 'block' : 'none';
    $('#linhaTaxa').style.display = tipo() === 'entrega' ? 'flex' : 'none';
    $('#vTaxa').textContent = M.taxa > 0 ? brl(M.taxa) : 'Grátis';
    $('#vSub').textContent = brl(subtotal());
    $('#vTot').textContent = brl(subtotal() + taxa());
    salvar();
  }
  function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; }
  document.addEventListener('click', function (e) {
    var a = e.target.closest('[data-add]'), d = e.target.closest('[data-dec]'), f = e.target.closest('[data-fecha]');
    if (a) { var id = a.getAttribute('data-add'); cart[id] = Math.min((cart[id] || 0) + 1, 50); render(); }
    if (d) { var id2 = d.getAttribute('data-dec'); cart[id2] = (cart[id2] || 0) - 1; render(); }
    if (f) all('.modal').forEach(function (m) { m.classList.remove('on'); });
  });
  all('.modal').forEach(function (m) { m.addEventListener('click', function (e) { if (e.target === m) m.classList.remove('on'); }); });
  $('#verCarrinho').addEventListener('click', function () { $('#erro').style.display = 'none'; $('#mCarrinho').classList.add('on'); });
  all('input[name=tipo]').forEach(function (r) { r.addEventListener('change', render); });
  $('#pag').addEventListener('change', function () { $('#trocoBox').style.display = this.value === 'dinheiro' ? 'block' : 'none'; });
  $('#busca').addEventListener('input', function () {
    var t = this.value.trim().toLowerCase(), vis = 0;
    all('section.cat').forEach(function (s) { var c = 0; s.querySelectorAll('.item').forEach(function (it) { var ok = !t || it.getAttribute('data-busca').indexOf(t) > -1; it.style.display = ok ? '' : 'none'; if (ok) c++; }); s.style.display = c ? '' : 'none'; vis += c; });
    $('#vazio').style.display = vis ? 'none' : 'block';
  });
  if ('IntersectionObserver' in window) {
    var chips = {}; all('nav.cats a').forEach(function (a) { chips[a.getAttribute('href').slice(1)] = a; });
    var io = new IntersectionObserver(function (es) { es.forEach(function (en) { if (en.isIntersecting) { all('nav.cats a').forEach(function (a) { a.classList.remove('on'); }); var c = chips[en.target.id]; if (c) { c.classList.add('on'); c.scrollIntoView({ block: 'nearest', inline: 'center' }); } } }); }, { rootMargin: '-80px 0px -70% 0px' });
    all('section.cat').forEach(function (s) { io.observe(s); });
  }
  function erro(m) { var e = $('#erro'); e.textContent = m; e.style.display = 'block'; }
  $('#confirmar').addEventListener('click', function () {
    if (!Object.keys(cart).length) return erro('Adicione pelo menos um item.');
    if ($('#nome').value.trim().length < 2) { $('#nome').focus(); return erro('Informe seu nome.'); }
    if (tipo() === 'entrega' && $('#endereco').value.trim().length < 6) { $('#endereco').focus(); return erro('Informe o endereço de entrega.'); }
    var b = this; b.disabled = true; b.textContent = 'Registrando pedido...';
    fetch('/webhook/cardapio-pedido', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({
      c: M.slug, itens: cart, obs: $('#obs').value, tipo: tipo(), endereco: $('#endereco').value, nome: $('#nome').value, pagamento: $('#pag').value, troco: $('#troco').value }) })
      .then(function (r) { return r.json(); })
      .then(function (j) {
        b.disabled = false; b.textContent = 'Confirmar pedido';
        if (!j.ok) return erro(j.erro || 'Não foi possível registrar o pedido.');
        cart = {}; render();
        $('#okNum').textContent = '#' + j.numero; $('#okZap').href = j.whatsapp_url;
        $('#pixBox').style.display = j.pix ? 'block' : 'none';
        if (j.pix) { $('#pixCod').value = j.pix; $('#pixVal').textContent = j.total_fmt; }
        $('#mCarrinho').classList.remove('on'); $('#mOk').classList.add('on');
      })
      .catch(function () { b.disabled = false; b.textContent = 'Confirmar pedido'; erro('Falha de conexão. Tente de novo.'); });
  });
  $('#copiarPix').addEventListener('click', function () { var t = $('#pixCod'); t.select(); (navigator.clipboard ? navigator.clipboard.writeText(t.value) : Promise.reject()).catch(function () { document.execCommand('copy'); }); this.textContent = 'Código copiado!'; });
  render();
})();
</script></body></html>`;
return [{ json: { codigo: 200, html } }];

const b = $('Novo pedido (POST)').first().json.body || {};
const slug = String(b.c || '');
let menu = null, cfg = null;
try { menu = JSON.parse($('Lê cardápio do pedido').first().json.menu || 'null'); } catch (e) {}
try { cfg = JSON.parse($('Lê config privada').first().json.cfg || 'null'); } catch (e) {}
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const falha = m => [{ json: { ok: false, erro: m } }];

if (!/^[a-z0-9-]{4,60}$/.test(slug) || !menu || !cfg) return falha('Cardápio não encontrado.');

// O preço vem do cardápio salvo, nunca do navegador
const tabela = {};
menu.categorias.forEach(c => c.itens.forEach(i => { if (i.preco !== null) tabela[i.id] = { nome: i.nome, preco: i.preco }; }));
(menu.combos || []).forEach(k => { tabela[k.id] = { nome: /^combo/i.test(k.nome) ? k.nome : 'Combo ' + k.nome, preco: k.preco }; });

const linhas = [];
for (const [id, q0] of Object.entries(b.itens && typeof b.itens === 'object' ? b.itens : {})) {
  const q = Math.floor(Number(q0));
  if (tabela[id] && q >= 1 && q <= 50) linhas.push({ id, nome: tabela[id].nome, qtd: q, preco: tabela[id].preco, total: Math.round(tabela[id].preco * q * 100) / 100 });
}
if (!linhas.length) return falha('Seu carrinho está vazio.');
if (linhas.length > 40) return falha('Pedido grande demais para o cardápio digital. Fale com a loja no WhatsApp.');

const L = menu.loja;
let tipo = b.tipo === 'entrega' && L.entrega ? 'entrega' : 'retirada';
if (tipo === 'retirada' && !L.retirada) tipo = 'entrega';
const nome = limpa(b.nome, 60), endereco = limpa(b.endereco, 200), obs = limpa(b.obs, 300);
if (nome.length < 2) return falha('Informe seu nome.');
if (tipo === 'entrega' && endereco.length < 6) return falha('Informe o endereço de entrega.');
const pagamento = ['pix', 'cartao', 'dinheiro'].includes(b.pagamento) ? (b.pagamento === 'pix' && !cfg.pix.ativo ? 'cartao' : b.pagamento) : 'cartao';
const troco = pagamento === 'dinheiro' ? Number(String(b.troco || '').replace(/[^\d,.]/g, '').replace(',', '.')) || 0 : 0;

const subtotal = Math.round(linhas.reduce((s, l) => s + l.total, 0) * 100) / 100;
const taxa = tipo === 'entrega' ? (L.taxa || 0) : 0;
const total = Math.round((subtotal + taxa) * 100) / 100;

return [{ json: { ok: true, slug, pedido: { nome, tipo, endereco: tipo === 'entrega' ? endereco : '', obs, pagamento, troco, linhas, subtotal, taxa, total, criadoEm: new Date().toISOString() } } }];

const v = $('Validar pedido').first().json;
const cfg = JSON.parse($('Lê config privada').first().json.cfg);
const menu = JSON.parse($('Lê cardápio do pedido').first().json.menu);
const numero = Number(Object.values($input.first().json)[0]) || 1;
const p = { numero, ...v.pedido };
const brl = x => 'R$ ' + Number(x).toFixed(2).replace('.', ',');

// Pix copia e cola (BR Code do Banco Central), gerado aqui mesmo, sem API
function emv(id, valor) { const s = String(valor); return id + String(s.length).padStart(2, '0') + s; }
function crc16(str) {
  let crc = 0xFFFF;
  for (let i = 0; i < str.length; i++) {
    crc ^= str.charCodeAt(i) << 8;
    for (let j = 0; j < 8; j++) { crc = (crc & 0x8000) ? ((crc << 1) ^ 0x1021) : (crc << 1); crc &= 0xFFFF; }
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}
function pixCopiaECola({ chave, nome, cidade, valor, txid }) {
