<h2>🧾 Últimos pedidos</h2>${pedidos.length ? `<div class="t"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Itens</th><th>Total</th></tr></thead><tbody>${linhas}</tbody></table></div>` : '<p class="m">Nenhum pedido ainda. Divulgue o link do cardápio!</p>'}`;
