</style></head><body>
<header class="capa"><span class="emo">${esc(D.emoji_capa)}</span><h1>${esc(L.nome)}</h1>${L.slogan ? `<p>${esc(L.slogan)}</p>` : ''}</header>
<div class="box"><div class="info">${info}</div><p class="bv">${esc(L.boas_vindas)}</p>
<div class="busca"><input id="busca" type="search" placeholder="🔎 Buscar no cardápio" aria-label="Buscar no cardápio"></div></div>
