<main class="box">${secoes.join('')}<p class="vazio" id="vazio">Nenhum item encontrado com essa busca.</p></main>
<footer>Cardápio digital de ${esc(L.nome)} · feito com IA</footer>

<div class="barra" id="barra"><button type="button" id="verCarrinho"><span>🛒 <span id="qtdTot">0 itens</span></span><span>Ver pedido · <span id="valTot">R$ 0,00</span></span></button></div>

<div class="modal" id="mCarrinho" role="dialog" aria-modal="true" aria-label="Seu pedido"><div class="sheet">
  <h2>Seu pedido <button class="x" type="button" data-fecha aria-label="Fechar">×</button></h2>
