    ${L.entrega ? `<label><input type="radio" name="tipo" value="entrega" checked> 🛵 Entrega</label>` : ''}
    ${L.retirada ? `<label><input type="radio" name="tipo" value="retirada" ${L.entrega ? '' : 'checked'}> 🏃 Retirar</label>` : ''}</div></div>
  <div id="endBox"><label for="endereco">Endereço de entrega</label><input id="endereco" maxlength="200" placeholder="Rua, número, bairro e referência"></div>
  <label for="nome">Seu nome</label><input id="nome" maxlength="60" placeholder="Como devemos te chamar?">
  <label for="pag">Pagamento</label><select id="pag">${L.aceita_pix ? '<option value="pix">💠 Pix (copia e cola)</option>' : ''}<option value="cartao">💳 Cartão na entrega/retirada</option><option value="dinheiro">💵 Dinheiro</option></select>
